// Clinical documentation: fill the blanks on the original form pages, then generate a filled copy
// that keeps the exact layout and fonts. Page images and blank positions come from
// tools/extract_forms.py (forms/forms.json, inlined below as CDF_FORMS).
// Field kinds: line (one-line blank), box (multi-line area), check (tick box), choice (options to circle).
// mask = the template prints sample text there (lorem ipsum, a sample date), so it is covered in white.
const CDF_K=1.45; // screen pixels per PDF point
let CDF_SAVE_T=0;
function cdfVals(key){CD_DATA.fills=CD_DATA.fills||{};return CD_DATA.fills[key]||(CD_DATA.fills[key]={})}
